public class PlatformIndependenceDemo {
    public static void main(String[] args) {
        // System properties expose the underlying host abstraction layer
        String osName = System.getProperty("os.name");
        String osArch = System.getProperty("os.arch");
        String javaVersion = System.getProperty("java.version");

        System.out.printf("Running identical bytecode on Host OS: [%s], Architecture: [%s] via JVM Version: [%s]%n", 
                          osName, osArch, javaVersion);
    }
}
